const b = $json.body ?? $json;
const instance = 'wa_empresa_00000000-0000-0000-0000-000000000000';
if (b.instance !== instance || String(b.event).toLowerCase().replace(/_/g, '.') !== 'messages.upsert') return null;
const d = b.data;
if (!d || Array.isArray(d) || d.key?.fromMe !== false || !d.key?.id) return null;
const jid = String(d.key.remoteJid ?? '');
if (jid.endsWith('@g.us') || jid.includes('broadcast') || jid.includes('newsletter')) return null;
const candidates = [jid, d.key.remoteJidAlt, d.remoteJidAlt];
const phoneJid = candidates.find(v => typeof v === 'string' && /^\d{10,15}@s\.whatsapp\.net$/.test(v));
if (!phoneJid) return null;
const text = d.message?.conversation ?? d.message?.extendedTextMessage?.text;
if (typeof text !== 'string' || !text.trim()) return null;
return {json: {
  empresa_id: '00000000-0000-0000-0000-000000000000',
  instancia: instance,
  telefone: phoneJid.split('@')[0],
  mensagem_id: String(d.key.id),
  texto: text.trim().slice(0, 4000),
  sessionId: '00000000-0000-0000-0000-000000000000:' + phoneJid.split('@')[0]
}};

const clientes = $json.body;
if (!Array.isArray(clientes)) throw new Error('Resposta inesperada ao consultar bloqueio');
if (clientes.some(c => c.bloqueado === true)) return null;
return {json: $('Verificar empresa ativa').item.json};

const text=$json.resposta;
if (typeof text!=='string'||!text.trim()) throw new Error('Banco não retornou resposta');
const origem=$('Validar mensagem').first().json;
return {json:{telefone:origem.telefone,instancia:origem.instancia,resposta:text}};

